WITH b AS (SELECT x FROM TABLE(hcm.system.raw_query('default', 'project-task-index-v1', '{"size":0,"aggs":{"c":{"composite":{"size":65000,"sources":[{"day":{"date_histogram":{"field":"Data.eventTime","calendar_interval":"day","format":"yyyy-MM-dd"}}},{"code":{"terms":{"field":"Data.boundaryHierarchyCode.district"}}},{"mode":{"terms":{"field":"Data.deliveryMode"}}},{"zd":{"terms":{"field":"Data.zeroDose","missing_bucket":true}}}]},"aggs":{"kids":{"cardinality":{"field":"Data.individualId","precision_threshold":40000}}}}},"query":{"term":{"Data.administrationStatus":"ADMINISTRATION_SUCCESS"}}}')) CROSS JOIN UNNEST(CAST(json_extract(result, '$.aggregations.c.buckets') AS array(json))) AS t(x))
SELECT CAST(json_extract_scalar(x, '$.key.day') AS date) AS event_date, d.region, d.district, d.boundary_code,
       CASE json_extract_scalar(x, '$.key.mode') WHEN 'FIXED_POST' THEN 'Fixed post' WHEN 'HOUSE_TO_HOUSE' THEN 'House to house' WHEN 'TRANSIT_POST' THEN 'Transit post' ELSE json_extract_scalar(x, '$.key.mode') END AS delivery_mode,
       CASE json_extract_scalar(x, '$.key.zd') WHEN 'true' THEN 'Zero-dose' WHEN 'false' THEN 'Previously vaccinated' ELSE 'Not recorded' END AS zero_dose_status,
       json_extract_scalar(x, '$.key.zd') = 'true' AS zero_dose, CAST(json_extract_scalar(x, '$.kids.value') AS bigint) AS children
FROM b JOIN microplan.public.dim_district d ON d.boundary_code = json_extract_scalar(x, '$.key.code')
